on conflict (id) do update set
  source_split = excluded.source_split,
  source_index = excluded.source_index,
  text = excluded.text,
  ground_truth = excluded.ground_truth,
  purpose = excluded.purpose,
  example_rationale = excluded.example_rationale;

do $$
declare
  task_count integer;
  example_count integer;
  label_count integer;
begin
  select count(*) into task_count from public.tweets where purpose = 'task';
  select count(*) into example_count from public.tweets where purpose = 'example';
  select count(distinct ground_truth) into label_count from public.tweets where purpose = 'task';
  if task_count <> 60 or example_count <> 6 or label_count <> 6 then
    raise exception 'Expected 60 task tweets, 6 examples, and all 6 labels; got %, %, %', task_count, example_count, label_count;
  end if;
end $$;
